#include <algorithm>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

void solve(istream& in, ostream& out) {
    int n;
    string stalls;
    in >> n >> stalls;
    vector<int> nextOriginal(n, 2 * n);
    int nearest = 2 * n;
    int previous = -n;
    int oldMinimum = n;
    for (int i = 0; i < n; ++i) {
        if (stalls[i] == '1') {
            oldMinimum = min(oldMinimum, i - previous);
            previous = i;
        }
    }
    for (int i = n - 1; i >= 0; --i) {
        if (stalls[i] == '1') nearest = i;
        nextOriginal[i] = nearest;
    }
    auto feasible = [&](int distance) {
        if (oldMinimum < distance) return false;
        int latest = -n;
        int added = 0;
        for (int i = 0; i < n; ++i) {
            if (stalls[i] == '1') {
                latest = i;
            } else if (i - latest >= distance &&
                       nextOriginal[i] - i >= distance) {
                latest = i;
                if (++added == 2) return true;
            }
        }
        return false;
    };
    int left = 1, right = n - 1, answer = 0;
    while (left <= right) {
        int middle = left + (right - left) / 2;
        if (feasible(middle)) {
            answer = middle;
            left = middle + 1;
        } else {
            right = middle - 1;
        }
    }
    out << answer << '\n';
}

int main() {
    ifstream in("socdist1.in");
    ofstream out("socdist1.out");
    solve(in, out);
    return 0;
}
