#include <algorithm>
#include <fstream>
#include <iostream>
#include <utility>
#include <vector>
using namespace std;

void solve(istream& in, ostream& out) {
    int n;
    in >> n;
    vector<pair<int, int>> cows(n);
    for (auto& cow : cows) in >> cow.first >> cow.second;
    sort(cows.begin(), cows.end());
    int threshold = 1000001;
    for (int i = 1; i < n; ++i) {
        if (cows[i].second != cows[i - 1].second) {
            threshold = min(threshold, cows[i].first - cows[i - 1].first);
        }
    }
    int seeds = 0;
    for (int i = 0; i < n; ++i) {
        if (cows[i].second == 1 &&
            (i == 0 || cows[i - 1].second == 0 ||
             cows[i].first - cows[i - 1].first >= threshold)) {
            ++seeds;
        }
    }
    out << seeds << '\n';
}

int main() {
    ifstream in("socdist2.in");
    ofstream out("socdist2.out");
    solve(in, out);
    return 0;
}
