#include <algorithm>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

struct Event {
    int time, a, b;
};

bool consistent(int patient, int limit, int n,
                const vector<Event>& events, const string& observed) {
    vector<unsigned char> infected(n, 0);
    vector<int> shakes(n, 0);
    infected[patient] = 1;
    for (const Event& event : events) {
        bool wasA = infected[event.a];
        bool wasB = infected[event.b];
        bool sendsA = wasA && ++shakes[event.a] <= limit;
        bool sendsB = wasB && ++shakes[event.b] <= limit;
        if (sendsA) infected[event.b] = 1;
        if (sendsB) infected[event.a] = 1;
    }
    for (int i = 0; i < n; ++i) {
        if (infected[i] != static_cast<unsigned char>(observed[i] - '0')) {
            return false;
        }
    }
    return true;
}

void solve(istream& in, ostream& out) {
    int n, t;
    string observed;
    in >> n >> t >> observed;
    vector<Event> events(t);
    for (Event& event : events) {
        in >> event.time >> event.a >> event.b;
        --event.a;
        --event.b;
    }
    sort(events.begin(), events.end(),
         [](const Event& a, const Event& b) { return a.time < b.time; });
    int patients = 0, minimum = t + 1, maximum = -1;
    bool infinity = false;
    for (int patient = 0; patient < n; ++patient) {
        if (observed[patient] != '1') continue;
        bool possible = false;
        for (int limit = 0; limit <= t; ++limit) {
            if (consistent(patient, limit, n, events, observed)) {
                possible = true;
                minimum = min(minimum, limit);
                maximum = max(maximum, limit);
                if (limit == t) infinity = true;
            }
        }
        patients += possible;
    }
    out << patients << ' ' << minimum << ' ';
    if (infinity) out << "Infinity\n";
    else out << maximum << '\n';
}

int main() {
    ifstream in("tracing.in");
    ofstream out("tracing.out");
    solve(in, out);
    return 0;
}
